UINT16 * RealTimeController::getTestLabelData()
{
	PrinterManager *p = dynamic_cast<PrinterManager *> (pFirstPrinter);
	if (p)
	{
		p->createTestLabel(PrCheckerboard);
		return ( p ) ? p->getTestLabelData() : 0;
	}
	return 0;
}

RealTimeController::~RealTimeController()
{
#ifdef USE_ACCOUNTANT
    util_acc::removeInstance(dataType);
#endif
	//shutdown the msg thread
    ShutdownNicely();

    // Deregister for all the OperationMode messages
    deregisterAllEvents();

    // delete the first item associated to the each usb node id list!

    // it is always the USBCommManager!!
    // The USBCommManager takes care of deleting its
    // associated managers!!

    // Delete all the Comm Managers
    Util::CLockCriticalSection lock( usbNodesCS );

    map< USBD_NODE_ID, list<DeviceType *> *>::iterator pos = usbDevices.begin();

    while (pos != usbDevices.end())
    {
        list<DeviceType *> *pList = pos->second;

        DeviceType *pDT = pList->front();

        // Delete the USBCommManager
        delete pDT->pHobThread;
        delete pDT;

        while (pList->size() > 0)
        {

            DeviceType *pDT = pList->front();
            pList->pop_front();

            delete pDT;
        }

        delete pList;

        pos++;
    }

	usbDevices.clear();

    map< USBD_NODE_ID, Hobart::CEvolMsgReceiver *>::iterator uPos = unknownDevices.begin();


    while (uPos != unknownDevices.end())
    {
        delete uPos->second;
        uPos++;
    }

	unknownDevices.clear();
}


void RealTimeController::processEvent( Util::CSmartPtr< EvolMessageWrapper> & msg )
{
    if ( msg.get() != NULL )
    {
        switch (msg->getDeviceType())
        {
            case OperationMode:
                {
                    Debug::trace("RealTimeController.Event", HobString("OperationMode Message: ") +
                            HobString(Integer::toString((UINT16) msg->getEventType())));
                    handleOperationModeEvent((OpModeEvent) msg->getEventType(), msg->Data());

                    break;
                }
            case ProductDev:
                {
                    Debug::trace("RealTimeController.Event", HobString("ProductDev Message: ") +
                            HobString(Integer::toString((UINT16) msg->getEventType())));
                    handleProductDevEvent((ProductEvent) msg->getEventType(), msg->Data());

                    break;
                }
            case Weigher:
                {
                    Debug::trace("RealTimeController.Event", HobString("Weigher Message: ") +
                            HobString(Integer::toString((UINT16) msg->getEventType())));
                    handleWeigherEvent((WgEvent) msg->getEventType(), msg->Data());

                    break;
                }
            case Numeric:
                {
                    Debug::trace("RealTimeController.Event", HobString("Numeric Message: ") +
                            HobString(Integer::toString((UINT16) msg->getEventType())));
                    handleNumericEvent((NmEvent) msg->getEventType(), msg->Data());;

                    break;
                }
            case Marquee:
                {
                    Debug::trace("RealTimeController.Event", HobString("Marquee Message: ") +
                            HobString(Integer::toString((UINT16) msg->getEventType())));
                    handleMarqueeEvent((MqEvent) msg->getEventType(), msg->Data());

                    break;
                }
            case Printer:
                {
                    Debug::trace("RealTimeController.Event", HobString("Printer Message: ") +
                            HobString(Integer::toString((UINT16) msg->getEventType())));
                    handlePrinterEvent((PrEvent) msg->getEventType(), msg->Data());

                    break;
                }
            case LabelApplier:
                {
                    Debug::trace("RealTimeController.Event", HobString("LabelApplier Message: ") +
                            HobString(Integer::toString((UINT16) msg->getEventType())));
                    handleLabelApplierEvent((LaEvent) msg->getEventType(), msg->Data());

                    break;
                }
            case Wrapper:
                {
                    Debug::trace("RealTimeController.Event", HobString("Wrapper Message: ") +
                            HobString(Integer::toString((UINT16) msg->getEventType())));
                    handleWrapperEvent((WrEvent) msg->getEventType(), msg->Data());

                    break;
                }
            case System:
                {
                    Debug::trace("RealTimeController.Event", HobString("System Message: ") +
                            HobString(Integer::toString((UINT16) msg->getEventType())));
                    handleSystemEvent((SysEvent) msg->getEventType(), msg->Data());

                    break;
                }
            default:
                {
                    break;
                }
        }

        Debug::trace("RealTimeController.Event", HobString("Message Completed"));
    }
}

void RealTimeController::timeoutProcess(__int32 timer_id)
{
	if ( WrapperProbe_ == timer_id ) {
		if ( !wrapperAttached )
		{
			std::string systemStyle = FpmManager::getInstance()->getMFGSystemStyle();

#if defined ( __linux__ )
			if ( ( systemStyle == "NGW3" ) || ( systemStyle == "NGW2" ) )
			{
				CanManager *pManager;

				if ( (pManager = CanManager::getInstance( CanManager::_PrimaryBus )) )
				{
					Debug::trace("RealTimeController.NGW", "Shutting down the can manager");
					pManager->shutdown();
			    }
			}
#endif
			Debug::trace("RealTimeController.NGW", "Wrapper lost start scanning.....");
			NGWGeneric wrScan(_WrNGWScan, this);
			dispatchEvent(&wrScan);
		}
	}

	if ( FPCProbe_ == timer_id ) {
		if( fpcProbeStarted_ ) {
			Debug::trace("RealTimeController.Probe", "Resetting FPC!!!.");

			string reset = "/bin/echo 0 >> /usr/local/gpio/hub1_enable/value";
			string result;
			PAL_absclass::PAL_executeWithResults(reset, result);
			PAL_absclass::PAL_sleep( 100 );
			reset = "/bin/echo 1 >> /usr/local/gpio/hub1_enable/value";
			PAL_absclass::PAL_executeWithResults(reset, result);
		} else {
			Debug::trace("RealTimeController.Probe", "ERROR should not be here!!!.");	
		}
	}

}

void RealTimeController::startWrapperProbeTimer()
{
    if ( isNextGenWrapperEnabled() )
    {
		SystemStartManager::shutdown();
		wrProbeStarted_ = true;
		Debug::trace("RealTimeController.TOF", "Poll timer started.");
    	createTimer(pollTime, WrapperProbe_, CHobartTimer::PERIODIC_TIMER);
    }
}

void RealTimeController::startFpcProbeTimer()
{
	Debug::trace("RealTimeController.Probe", "Poll timer started.");
	fpcProbeStarted_ = true;
	createTimer(pollTimeFpc, FPCProbe_, CHobartTimer::PERIODIC_TIMER);
}

void RealTimeController::stopFpcProbeTimer()
{
	fpcProbeStarted_ = false;
	cancelTimer(FPCProbe_);
	Debug::trace("RealTimeController.Probe", "Poll timer stopped.");
}

void RealTimeController::stopWrapperProbeTimer()
{
	Debug::trace("RealTimeController.NGW", "stopWrapperProbeTimer()");

	wrProbeStarted_ = false;
	cancelTimer(WrapperProbe_);
}

void RealTimeController::USBPrinterAttached(
        USBD_NODE_ID nodeId,
        UINT16 UNUSED(releaseNumber),
        PrinterKind UNUSED(prKind))
{
    UNREFERENCED_PARAMETER(prKind);
    UNREFERENCED_PARAMETER(releaseNumber);

    Debug::trace("RealTimeController.Attach", "USBPrinterAttached -- Entry");

    Util::CLockCriticalSection lock( usbNodesCS );

    list<DeviceType *> *pList = NULL;
    map< USBD_NODE_ID, list<DeviceType *> *>::iterator pos;

    if ((pos = usbDevices.find(nodeId)) == usbDevices.end())
    {
        pList = new list<DeviceType *>;

        usbDevices.insert(make_pair(nodeId, pList));
    }
    else
    {
        pList = pos->second;
    }

    // Create a new thread
    DeviceType *pDT = new DeviceType;
Debug::trace("RealTimeController.Attach", "Printer pDT: " + Hex::toString((long)(long)pDT ) ); 
    pDT->pHobThread = new PrinterCommManager(nodeId, UsbManager::getInstance()->getUsbDescs( nodeId )  );
    pDT->evolDevType = Printer;

    pList->push_back(pDT);

    Debug::trace("RealTimeController.Attach", "USBPrinterAttached -- Exit");
	MessageLogger::logMessage(MessageLogger::ScaleEventsLog, "USBPrinterAttached("  + Hex::toString((long long)nodeId) + ").");
}

