void RealTimeController::USBWrapperAttached(USBD_NODE_ID nodeId, UINT16 UNUSED(releaseNumber))
{
	UNREFERENCED_PARAMETER(releaseNumber);
	Debug::trace("RealTimeController.Attach", HobString("USBWrapperAttached(") + Hex::toString(nodeId) + ")");

	if ( !wrapperAttached )
	{
		Debug::trace("RealTimeController.Attach", HobString("stopping wrapper probe..."));
    	stopWrapperProbeTimer();
	}

	wrapperAttached = true;

    Util::CLockCriticalSection lock( usbNodesCS );

    list<DeviceType *> *pList = NULL;
	map< USBD_NODE_ID, list<DeviceType *> *>::iterator pos;

	if ((pos = usbDevices.find(nodeId)) == usbDevices.end())
	{
		pList = new list<DeviceType *>;
		if (pList == 0)
		{
			Debug::trace("RealTimeController.Attach", HobString("USBWrapperAttached(") + Hex::toString((long long)nodeId) + ") -  Could not create pList!");
			return;
		}
		usbDevices.insert(make_pair(nodeId, pList));
	}
	else
	{
		pList = pos->second;
		Debug::trace("RealTimeController.Attach", HobString("USBWrapperAttached():  nodeId IS in usbDevices."));
	}

	// Create a new thread
	DeviceType *pDT = new DeviceType;
	Debug::trace("RealTimeController.Attach", "Wrapper pDT: " + Hex::toString((long)(long)pDT ) ); 
	if (pDT == 0)
	{
		Debug::trace("RealTimeController.Attach", HobString("USBWrapperAttached(") + Hex::toString((long long)nodeId) + ") -  Could not create DeviceType!");
		return;
	}

	pDT->pHobThread = new EvolWrapperCommManager(nodeId, UsbManager::getInstance()->getUsbDescs( nodeId ) );
	if (pDT->pHobThread == 0)
	{
		Debug::trace("RealTimeController.Attach", HobString("USBWrapperAttached(") + Hex::toString((long long)nodeId) + ") -  Could not create EvolWrapperCommManager!");
		delete pDT;
		return;
	}
	pDT->evolDevType = Wrapper;

	pList->push_back(pDT);
	Debug::trace("RealTimeController.Attach", HobString("USBWrapperAttached(") + Hex::toString((long long)nodeId) + ") -  Done. pList->size() = " + Integer::toString((int)pList->size()));
	MessageLogger::logMessage(MessageLogger::ScaleEventsLog, "USBWrapperAttached("  + Hex::toString((long long)nodeId) + ") - Done.");
}

