// AWS Weighing Device (Atmel-based SAM-BA device) (haberrc)
void RealTimeController::USBWeigherAttached(USBD_NODE_ID nodeId, UINT16 UNUSED(releaseNumber), WeigherKind wgKind)
{
    UNREFERENCED_PARAMETER(releaseNumber);

    Util::CLockCriticalSection lock( usbNodesCS );

    list<DeviceType *> *pList = NULL;
    map< USBD_NODE_ID, list<DeviceType *> *>::iterator pos;

    if ((pos = usbDevices.find(nodeId)) == usbDevices.end())
    {
        pList = new list<DeviceType *>;
		if (pList == 0)
		{
			Debug::trace("RealTimeController.Attach", HobString("USBWeigherAttached(") + Hex::toString((long long)nodeId) + ") -  Could not create pList!");
			return;
		}
		Debug::trace("RealTimeController.Attach", HobString("USBWeigherAttached(") + Hex::toString((long long)nodeId) + ") - pList = new list<DeviceType *> = " + Hex::toString(PtrToUlong(pList)));

        usbDevices.insert(make_pair(nodeId, pList));
        Debug::trace("RealTimeController.Attach", HobString("USBWeigherAttached: added nodeId ") + Hex::toString((long long)nodeId));
    }
    else
    {
        pList = pos->second;
		Debug::trace("RealTimeController.Attach", HobString("USBWeigherAttached(") + Hex::toString((long long)nodeId) + ") - pList = pos->second = " + Hex::toString(PtrToUlong(pList)));
    }


    // Create a new thread
    DeviceType *pDT = new DeviceType;
	Debug::trace("RealTimeController.Attach", "Weigher create pDT: " + Hex::toString((long long)pDT) );
	if (pDT == 0)
	{
		Debug::trace("RealTimeController.Attach", HobString("USBWeigherAttached(") + Hex::toString((long long)nodeId) + ") -  Could not create DeviceType!");
		return;
	}

	pDT->pHobThread = new WeigherCommManager(nodeId, UsbManager::getInstance()->getUsbDescs( nodeId ), wgKind);
	//pWeigherComm = pDT->pHobThread;
	//Debug::trace("RealTimeController.Comm", "Attach pWeigherComm: " + Hex::toString((long long)pWeigherComm) );
	Debug::trace("RealTimeController.Attach", "pDT->pHobThread: " + Hex::toString((long long)pDT->pHobThread) );
	if (pDT->pHobThread == 0)
	{
		Debug::trace("RealTimeController.Attach", HobString("USBWeigherAttached(") + Hex::toString((long long)nodeId) + ") -  Could not create WeigherCommManager!");
		delete pDT;
		return;
	}
	Debug::trace("RealTimeController.Attach", "pDT->pHobThread: " + Hex::toString((long long)pDT->pHobThread));
    pDT->evolDevType = Weigher;

    pList->push_back(pDT);
	Debug::trace("RealTimeController.Attach", HobString("USBWeigherAttached(") + Hex::toString((long long)nodeId) + ") -  Done. pList->size() = " + Integer::toString((int)pList->size()));
	MessageLogger::logMessage(MessageLogger::ScaleEventsLog, "USBWeigherAttached("  + Hex::toString((long long)nodeId) + ").");
}

void RealTimeController::USBDeviceDetached(USBD_NODE_ID nodeId)
{
    findAndDetachDevice(nodeId, false);
}

void RealTimeController::CANDeviceDetached(NGWCANDevices device)
{
	Debug::trace("RealTimeController.Remove", "CANDeviceDetached(): " + Integer::toString(device));
	if( device == _FirstCANPrinter )
		delete pFirstPrinter;
	if( device == _SecondCANPrinter )
		delete pSecondPrinter;
	if( device == _ThirdCANPrinter )
		delete pThirdPrinter;
	if( device == _CANWeigher )
		delete pWeigherManager;
	if( device == _CANWrapper ) {
		delete pWrapperManager;
		delete pLabelApplierManager;
		wrapperAttached = false;
	}

}

void RealTimeController::detachUSBAPC()
{
	if ( !apcNodeID )
		return;

    Debug::trace("RealTimeController.Remove", HobString("detachUSBAPC: entry. remove APC device: ") + Hex::toString(apcNodeID));
	findAndDetachDevice(apcNodeID, false);
}

void RealTimeController::detachFakePrinter(USBD_NODE_ID nodeId)
{
    Debug::trace("RealTimeController.Remove", HobString("detachFakePrinter: entry. remove Fake PrinterManager, nodeId: ") + Long::toString(nodeId));

    Util::CLockCriticalSection lock( usbNodesCS );

    map< USBD_NODE_ID, Hobart::CEvolMsgReceiver *>::iterator posUnk;

    //
    // Search the map of unknown devices first. If the node isn't
    // found in the unknown device map, search for it in the main map.
    //
    if ((posUnk = unknownDevices.find(nodeId)) != unknownDevices.end())
    {
        Debug::trace("RealTimeController.Remove", HobString("deleting unknown device - CEvolMsgReceiver:") + Hex::toString((long long)posUnk->second) );
		if (posUnk->second)
		{
			PrinterManager *p = dynamic_cast<PrinterManager *> (posUnk->second);
			if (p)
			{
				PrinterType pType = p->getPrinterType();

				currentModeCS.Enter(); // FT-1115
				if ( pCurrentMode )
				{
					if ( pType == FirstPrinter )
						pCurrentMode->firstPrinterDetached();
					else if ( pType == SecondPrinter )
						pCurrentMode->secondPrinterDetached();
					else if ( pType == ThirdPrinter )
						pCurrentMode->thirdPrinterDetached();
				}
				currentModeCS.Leave(); // FT-1115

				if ( pType == FirstPrinter )
					pFirstPrinter = 0;
				else if ( pType == SecondPrinter )
					pSecondPrinter = 0;
				else if ( pType == ThirdPrinter )
					pThirdPrinter = 0;
			}
			delete posUnk->second;
		}
        unknownDevices.erase(posUnk);
    }
 }

void RealTimeController::removingPrinterManager( Hobart::CEvolMsgReceiver *pPrinterMgr )
{
	if (!pPrinterMgr)
		return;

	if ( pFirstPrinter == pPrinterMgr )
	{
		Debug::trace("RealTimeController.PrinterManager", HobString("removingPrinterManager- Someone is deleting a first PrinterManager that I knew about **and probably created for them**, so I'm getting rid of my references to it: 0x") + ptrtostring(pPrinterMgr));
		if (pCurrentMode)
		{
			currentModeCS.Enter();
			pCurrentMode->firstPrinterDetached();
			currentModeCS.Leave();
		}
		peripheralList.setFirstPrinter(NoPrinter);
		pFirstPrinter = 0;
		pFirstPrinterComm = 0;
	}
	if ( pSecondPrinter == pPrinterMgr )
	{
		Debug::trace("RealTimeController.PrinterManager", HobString("removingPrinterManager- Someone is deleting a second PrinterManager that I knew about **and probably created for them**, so I'm getting rid of my references to it: 0x") + ptrtostring(pPrinterMgr));
		if (pCurrentMode)
		{
			currentModeCS.Enter();
			pCurrentMode->secondPrinterDetached();
			currentModeCS.Leave();
		}
		peripheralList.setSecondPrinter(NoPrinter);
		pSecondPrinter = 0;
		pSecondPrinterComm = 0;
	}
	if ( pThirdPrinter == pPrinterMgr )
	{
		Debug::trace("RealTimeController.PrinterManager", HobString("removingPrinterManager- Someone is deleting a third PrinterManager that I knew about **and probably created for them**, so I'm getting rid of my references to it: 0x") + ptrtostring(pPrinterMgr));
		if (pCurrentMode)
		{
			currentModeCS.Enter();
			pCurrentMode->thirdPrinterDetached();
			currentModeCS.Leave();
		}
		peripheralList.setThirdPrinter(NoPrinter);
		pThirdPrinter = 0;
		pThirdPrinterComm = 0;
	}
}

void RealTimeController::removingWeigherManager( Hobart::CEvolMsgReceiver *pWeigherMgr )
{
	if ( pWeigherMgr && pWeigherManager == pWeigherMgr )
	{
		Debug::trace("RealTimeController.WeigherManager", HobString("removingWeigherManager - Someone is deleting a WeigherManager that I knew about **and probably created for them**, so I'm getting rid of my references to it: 0x") + ptrtostring(pWeigherMgr));
		pWeigherManager = 0;
		if (pCurrentMode)
		{
			currentModeCS.Enter();
			pCurrentMode->weigherDetached();
			currentModeCS.Leave();
		}
		peripheralList.setFirstWeigher(WgNoWeigher);
	}
}

void RealTimeController::findAndDetachDevice(USBD_NODE_ID nodeId, bool isSocketConn)
{
    Util::CLockCriticalSection lock( usbNodesCS );

    Hobart::CEvolMsgReceiver *pDeleteComm = NULL;
    string strMsg;
    map< USBD_NODE_ID, list<DeviceType *> *>::iterator pos;
    map< USBD_NODE_ID, Hobart::CEvolMsgReceiver *>::iterator posUnk;

	bool isTracing = Debug::isTracing("RealTimeController.Remove");
	if (isTracing)
	{
		Debug::trace("RealTimeController.Remove", HobString("findAndDetachDevice(") + Hex::toString((long long)nodeId) + "):  Entry");

		Debug::trace("RealTimeController.Remove", HobString("pWeigherManager: 0x") + Hex::toString((long long)pWeigherManager));
		Debug::trace("RealTimeController.Remove", HobString("pFirstPrinter: 0x") + Hex::toString((long long)pFirstPrinter));
		Debug::trace("RealTimeController.Remove", HobString("pSecondPrinter: 0x") + Hex::toString((long long)pSecondPrinter));
		Debug::trace("RealTimeController.Remove", HobString("pThirdPrinter: 0x") + Hex::toString((long long)pThirdPrinter));
	}

    //
    // Search the map of unknown devices first. If the node isn't
    // found in the unknown device map, search for it in the main map.
    //

    if ((posUnk = unknownDevices.find(nodeId)) != unknownDevices.end())
    {
		if (isTracing)
			Debug::trace("RealTimeController.Remove", HobString("deleting unknown device - CEvolMsgReceiver:") + Hex::toString((long long)posUnk->second) );
		if (posUnk->second)
			delete posUnk->second;

        unknownDevices.erase(posUnk);
    }
    else if((pos = usbDevices.find(nodeId)) != usbDevices.end())
    {
		currentModeCS.Enter(); // SOF-5518

        bool delCommManager = true;
        list<DeviceType *> *pList = pos->second;

        DeviceType *pDT = pList->front();

		if (isTracing)
			Debug::trace("RealTimeController.Remove", "findAndDetachDevice() pDT: " + Hex::toString((long long)pDT) );

		// Just FYI.  The APC firmware is being reported as: pDT->evolDevType == ESCPrinter,  but the following if doesn't check for it.
		// It will be handled ok since delCommManager=true, checked after all the conditionals.
        if (pDT->evolDevType == Printer)
        {
            //
            // special handling required for PrinterCommManager
            //

			if (isTracing)
				Debug::trace("RealTimeController.Remove", HobString("detaching device type 'Printer' ") + Hex::toString((int)pDT->evolDevType));

            PrinterCommManager *pPrinterComm = dynamic_cast<PrinterCommManager *> (pDT->pHobThread);
            delCommManager = detachPrinterComm(pPrinterComm, isSocketConn);
			if (isTracing)
				Debug::trace("RealTimeController.Remove", HobString("deleting device type 'Printer' ") + Hex::toString((int)pDT->evolDevType));
			MessageLogger::logMessage(MessageLogger::ScaleEventsLog, "USB Device detached: Printer ("  + Hex::toString((long long)nodeId) + ").");
        }
        else if (pDT->evolDevType == Wrapper)
        {
        	if ( wrapperAttached )
        	{
                Debug::trace("RealTimeController.Wrapper", HobString("starting wrapper probe..."));
        		startWrapperProbeTimer();
        	}

        	wrapperAttached = false;
			if (isTracing)
				Debug::trace("RealTimeController.Remove", HobString("deleting device type 'Wrapper' ") + Hex::toString((int)pDT->evolDevType));
			MessageLogger::logMessage(MessageLogger::ScaleEventsLog, "USB Device detached: Wrapper ("  + Hex::toString((long long)nodeId) + ").");
        }
        else if (pDT->evolDevType == Weigher)
        {
			//if( pWeigherComm != NULL ) {
			//	Debug::trace("RealTimeController.Comm", HobString("deleting pWeigherComm: ") + Hex::toString((long)(long)pWeigherComm));
			//		delete pWeigherComm;
			//	pWeigherComm = NULL;
			//} else {
			//	Debug::trace("RealTimeController.Comm", HobString("cannot delete pWeigherComm: ") + Hex::toString((long)(long)pWeigherComm));
			//}
			WeigherCommManager *pComm = dynamic_cast<WeigherCommManager *> (pDT->pHobThread);
			if (isTracing)
			{
				Debug::trace("RealTimeController.Remove", HobString("deleting device type 'Weigher' ") + Hex::toString((int)pDT->evolDevType));
				Debug::trace("RealTimeController.Remove", HobString("deleting device type 'Comm' ") + Hex::toString((long)(long)pDT->pHobThread));
				Debug::trace("RealTimeController.Remove", HobString("deleting device type 'pComm' ") + Hex::toString((long)(long)pComm));
			}
			MessageLogger::logMessage(MessageLogger::ScaleEventsLog, "USB Device detached: Weigher ("  + Hex::toString((long long)nodeId) + ").");
        }
        else if (pDT->evolDevType == LabelApplier)
        {
			if (isTracing)
				Debug::trace("RealTimeController.Remove", HobString("deleting device type 'LabelApplier' ")  + Hex::toString((int)pDT->evolDevType));
			MessageLogger::logMessage(MessageLogger::ScaleEventsLog, "USB Device detached: LabelApplier ("  + Hex::toString((long long)nodeId) + ").");
        }
        else
        {
			if (isTracing)
				Debug::trace("RealTimeController.Remove", HobString("deleting unnamed device type ") + Hex::toString((int)pDT->evolDevType));
			MessageLogger::logMessage(MessageLogger::ScaleEventsLog, "USB Device detached: Unnamed ("  + Hex::toString((long long)nodeId) + ").");
        }

        if (delCommManager == true)
        {
            // Delete the USBCommManager
            pDeleteComm = pDT->pHobThread;
            int n=0;

			if (isTracing)
			{
				Debug::trace("RealTimeController.Remove", HobString("deleting pHobThread: ") + Hex::toString((long)(long)pDeleteComm));

				Debug::trace("RealTimeController.Remove", HobString("pWeigherManager: 0x") + Hex::toString((long long)pWeigherManager));
				Debug::trace("RealTimeController.Remove", HobString("pFirstPrinter: 0x") + Hex::toString((long long)pFirstPrinter));
				Debug::trace("RealTimeController.Remove", HobString("pSecondPrinter: 0x") + Hex::toString((long long)pSecondPrinter));
				Debug::trace("RealTimeController.Remove", HobString("pThirdPrinter: 0x") + Hex::toString((long long)pThirdPrinter));
			}

            while (pList->size() > 0)
            {
				if (isTracing)
					Debug::trace("RealTimeController.Remove", HobString("deleting list element ") + Hex::toString(n++));
                delete pList->front();
                pList->pop_front();
            }

			if (isTracing)
				Debug::trace("RealTimeController.Remove", HobString("deleting list object"));
            delete pList;
			pList = 0;

			if (isTracing)
				Debug::trace("RealTimeController.Remove", HobString("removing node from usbDevices map"));
            usbDevices.erase(pos);

			if (isTracing)
				Debug::trace("RealTimeController.Remove", HobString("deleting comm manager") + Hex::toString((long)(long)pDeleteComm));
            delete pDeleteComm;
			pDeleteComm = 0;

			if (isTracing)
			{
				Debug::trace("RealTimeController.Remove", HobString("pWeigherManager: 0x") + Hex::toString((long long)pWeigherManager));
				Debug::trace("RealTimeController.Remove", HobString("pFirstPrinter: 0x") + Hex::toString((long long)pFirstPrinter));
				Debug::trace("RealTimeController.Remove", HobString("pSecondPrinter: 0x") + Hex::toString((long long)pSecondPrinter));
				Debug::trace("RealTimeController.Remove", HobString("pThirdPrinter: 0x") + Hex::toString((long long)pThirdPrinter));
			}
		}
        else
        {
			if (isTracing)
				Debug::trace("RealTimeController.Remove", HobString("comm manager NOT deleted for node ") + Hex::toString((long long)nodeId) );
        }

		if (isTracing)
			Debug::trace("RealTimeController.Remove", HobString("before currentModeCS.Leave()"));

		currentModeCS.Leave(); // SOF-5518

		if (isTracing)
		{
			Debug::trace("RealTimeController.Remove", HobString("after currentModeCS.Leave()"));
			Debug::trace("RealTimeController.Remove", HobString("pWeigherManager: 0x") + Hex::toString((long long)pWeigherManager));
			Debug::trace("RealTimeController.Remove", HobString("pFirstPrinter: 0x") + Hex::toString((long long)pFirstPrinter));
			Debug::trace("RealTimeController.Remove", HobString("pSecondPrinter: 0x") + Hex::toString((long long)pSecondPrinter));
			Debug::trace("RealTimeController.Remove", HobString("pThirdPrinter: 0x") + Hex::toString((long long)pThirdPrinter));
		}
    }
    else
    {
        // node not found in any maps
		if (isTracing)
			Debug::trace("RealTimeController.Remove", HobString("ERROR: node not found in map, can't delete comm manager object for node ") + Hex::toString((long long)nodeId) );
    }
	if (isTracing)
		Debug::trace("RealTimeController.Remove", HobString("findAndDetachDevice: exit"));
}

Hobart::CEvolMsgReceiver * RealTimeController::findCommManager(USBD_NODE_ID nodeId)
{
    Util::CLockCriticalSection lock( usbNodesCS );

    map< USBD_NODE_ID, list<DeviceType *> *>::iterator pos;

    if((pos = usbDevices.find(nodeId)) != usbDevices.end())
    {
        list<DeviceType *> *pList = pos->second;

        DeviceType *pDT = pList->front();

        return pDT->pHobThread;
    }

    return 0;
}


bool RealTimeController::detachPrinterComm(PrinterCommManager *pPrinterComm, bool UNUSED(isSocketConn))
{
    UNREFERENCED_PARAMETER(isSocketConn);
    bool delCommManager = true;

    if (delCommManager == true)
    {
        if (pFirstPrinterComm == pPrinterComm)
        {
        	Debug::trace("RealTimeController.Remove", "detachPrinterComm(): " );
            pFirstPrinter = NULL;
            pFirstPrinterComm = NULL;
            Debug::trace("RealTimeController.PrinterManager", HobString("pFirstPrinter: 0x") + Hex::toString((long long) pFirstPrinter));
            Debug::trace("RealTimeController.PrinterCommManager", HobString("pFirstPrinterComm: 0x") + Hex::toString((long long) pFirstPrinterComm));
        }
        else if (pSecondPrinterComm == pPrinterComm)
        {
            pSecondPrinter = NULL;
            pSecondPrinterComm = NULL;
            Debug::trace("RealTimeController.PrinterManager", HobString("pSecondPrinter: 0x") + Hex::toString((long long) pSecondPrinter));
            Debug::trace("RealTimeController.PrinterCommManager", HobString("pSecondPrinterComm: 0x") + Hex::toString((long long) pSecondPrinterComm));
        }
        else if (pThirdPrinterComm == pPrinterComm)
        {
            pThirdPrinter = NULL;
            pThirdPrinterComm = NULL;
            Debug::trace("RealTimeController.PrinterManager", HobString("pThirdPrinter: 0x") + Hex::toString((long long) pThirdPrinter));
            Debug::trace("RealTimeController.PrinterCommManager", HobString("pThirdPrinterComm: 0x") + Hex::toString((long long) pThirdPrinterComm));
        }
        else
        {
            // Create some configuration error!
            Debug::trace("RealTimeController.PrinterManager", "Some Printer Configuration = NULL");
        }
    }

    return delCommManager;
}

Hobart::CEvolMsgReceiver *RealTimeController::NewESCPrinter(
	USBD_NODE_ID nodeId,
	Hobart::CEvolMsgReceiver *pCreationDevice,
	PrinterTeachTable *pPrinterTeachTable,
	PrinterType printerType,
	LabelWidth labelWidth,
	UINT16 bufferSize,
	UINT16 printheadSize,
	UINT16 physicalAddress,
	PrinterKind prKind )
{
    PrinterManager *pHT = NULL;

	//SOF-3259 no 2nd or 3rd labels - Debug::trace("PrinterManager.checkForVirtualPrinting", "RTC.NewESCPrinter() START");

    if (printerType == FirstPrinter)
    {
        if (pFirstPrinter == NULL)
        {
            peripheralList.setFirstPrinter(prKind);
            dispatchEvent(&peripheralList);

            pFirstPrinter = pHT = new PrinterManager(
				pCreationDevice,
				pPrinterTeachTable,
				printerType,
				labelWidth,
				bufferSize,
				printheadSize,
				physicalAddress,
				nodeId,
				prKind);

            // Give the new PrinterManager some time to execute, at least so it can register for its messages,
            // since the call to firstPrinterAttached() will dispatch one the new PrinterManager is interested in.
			PAL_absclass::PAL_sleep( 1 );

            currentModeCS.Enter(); // FT-1115
            if ( pCurrentMode )
            	pCurrentMode->firstPrinterAttached(pFirstPrinter);
            currentModeCS.Leave(); // FT-1115

            Debug::trace("RealTimeController.PrinterManager", HobString("pFirstPrinter: 0x") + Hex::toString((long long) pFirstPrinter));
        }
        else
        {
            // Negotiation Strategy
            printerType = SecondPrinter;
        }
    }

    if (printerType == SecondPrinter)
    {
    	PrinterManager *mgr( dynamic_cast<PrinterManager*>( pSecondPrinter ) );

		if ( mgr )
			if ( mgr->isFakePrinterManager() )
				detachFakePrinter( mgr->getUsbNodeId() );

        if (pSecondPrinter == NULL)
        {
            peripheralList.setSecondPrinter(prKind);
            dispatchEvent(&peripheralList);

            pSecondPrinter = pHT = new PrinterManager(
				pCreationDevice,
				pPrinterTeachTable,
				printerType,
				labelWidth,
				bufferSize,
				printheadSize,
				physicalAddress,
				nodeId,
				prKind);

            // Give the new PrinterManager some time to execute, at least so it can register for its messages,
            // since the call to firstPrinterAttached() will dispatch one the new PrinterManager is interested in.
			PAL_absclass::PAL_sleep( 1 );

            currentModeCS.Enter(); // FT-1115
            if ( pCurrentMode )
            	pCurrentMode->secondPrinterAttached(pSecondPrinter);
            currentModeCS.Leave(); // FT-1115

            Debug::trace("RealTimeController.PrinterManager", HobString("pSecondPrinter: 0x") + Hex::toString((long long) pSecondPrinter));
        }
        else
        {
            // Negotiation Strategy
            printerType = ThirdPrinter;
        }
    }

    if (printerType == ThirdPrinter)
    {
    	PrinterManager *mgr( dynamic_cast<PrinterManager*>( pThirdPrinter ) );

		if ( mgr )
			if ( mgr->isFakePrinterManager() )
				detachFakePrinter(mgr->getUsbNodeId());

        if (pThirdPrinter == NULL)
        {
            peripheralList.setThirdPrinter(prKind);
            dispatchEvent(&peripheralList);

            pThirdPrinter = pHT = new PrinterManager(
				pCreationDevice,
				pPrinterTeachTable,
				printerType,
				labelWidth,
				bufferSize,
				printheadSize,
				physicalAddress,
				nodeId,
				prKind);

            // Give the new PrinterManager some time to execute, at least so it can register for its messages,
            // since the call to firstPrinterAttached() will dispatch one the new PrinterManager is interested in.
			PAL_absclass::PAL_sleep( 1 );

            currentModeCS.Enter(); // FT-1115
            if ( pCurrentMode )
            	pCurrentMode->thirdPrinterAttached(pThirdPrinter);
            currentModeCS.Leave(); // FT-1115

            Debug::trace("RealTimeController.PrinterManager", HobString("pThirdPrinter: 0x") + Hex::toString((long long) pThirdPrinter));
        }
        else
        {
            // Negotiation Strategy
        }
    }

    if (pHT != NULL)
    {
        DeviceType *pDT( new DeviceType );
		pDT->pHobThread = pHT;
        pDT->evolDevType = Printer;

        Util::CLockCriticalSection lock( usbNodesCS );
        list<DeviceType *> *pList = usbDevices[nodeId];

        // Add it to the list of Peripherals attached to this usb node.
		if (pList)
			pList->push_back(pDT);
    }

    checkForVirtualPrinting();

	//SOF-3259 no 2nd or 3rd labels - Debug::trace("PrinterManager.checkForVirtualPrinting", "RTC.NewESCPrinter() END");

	return pHT;
}


//PrinterManager *RealTimeController::NewFakePrinter(USBD_NODE_ID nodeId,
Hobart::CEvolMsgReceiver *RealTimeController::NewFakePrinter(USBD_NODE_ID nodeId,
        Hobart::CEvolMsgReceiver *pCreationDevice,
        PrinterTeachTable *pPrinterTeachTable,
        PrinterType printerType,
        LabelWidth labelWidth,
        UINT16 bufferSize,
        UINT16 printheadSize,
        UINT16 physicalAddress,
        PrinterKind prKind)
{
	if ( (printerType == FirstPrinter && !pFirstPrinter) ||
	     (printerType == SecondPrinter && !pSecondPrinter) ||
	     (printerType == ThirdPrinter && !pThirdPrinter) )
	{
		PrinterManager *pHT = new PrinterManager(pCreationDevice,
													pPrinterTeachTable,
													printerType,
													labelWidth,
													bufferSize,
													printheadSize,
													physicalAddress,
													nodeId,
													prKind);
		if (pHT)
		{
			// Give the new PrinterManager some time to execute, at least so it can register for its messages,
			// since the call to firstPrinterAttached() will dispatch one the new PrinterManager is interested in.
			PAL_absclass::PAL_sleep( 1 );
			Debug::trace("RealTimeController.PrinterManager", "fakePrinterManager printerType:" + Integer::toString((int)printerType) + " mgr: 0x" + Hex::toString((long long) pHT));

			currentModeCS.Enter(); // FT-1115

			if ( printerType == FirstPrinter )
			{
				pFirstPrinter = pHT;
				if ( pCurrentMode )
					pCurrentMode->firstPrinterAttached(pFirstPrinter);
			}
			else if ( printerType == SecondPrinter )
			{
				pSecondPrinter = pHT;
				if ( pCurrentMode )
					pCurrentMode->secondPrinterAttached(pSecondPrinter);
			}
			else if ( printerType == ThirdPrinter )
			{
				pThirdPrinter = pHT;
				if ( pCurrentMode )
					pCurrentMode->thirdPrinterAttached(pThirdPrinter);
			}

			currentModeCS.Leave(); // FT-1115

		    Util::CLockCriticalSection lock( usbNodesCS );

		    unknownDevices.insert(make_pair(nodeId, pHT));
			checkForVirtualPrinting();

			return pHT;
		}
	}
	return 0;
}


// This function returns NULL if the printer attempting to be inserted into the system
// can not full the desired Primary, Secondary, or Tercerary Position in the system!
Hobart::CEvolMsgReceiver *RealTimeController::NewUSBPrinter(
	USBD_NODE_ID nodeId,
	Hobart::CEvolMsgReceiver *pCreationDevice,
	PrinterTeachTable *pPrinterTeachTable,
	PrinterType printerType,
	LabelWidth labelWidth,
	UINT16 bufferSize,
	UINT16 printheadSize,
	UINT16 physicalAddress,
	PrinterKind prKind)
{
    Util::CLockCriticalSection lock( usbNodesCS );

    PrinterCommManager *pNewPComm( dynamic_cast<PrinterCommManager*> ( pCreationDevice ) );
    PrinterManager *pHT( NULL );

	//SOF-3259 no 2nd or 3rd labels - Debug::trace("PrinterManager.checkForVirtualPrinting", "RTC.NewUSBPrinter() START");
    
	Debug::trace("RealTimeController.PrinterManager", HobString("NewUSBPrinter() - nodeId: 0x") + Hex::toString((long long) nodeId));
    Debug::trace("RealTimeController.PrinterManager", HobString("NewUSBPrinter() - printerType: ") + Integer::toString((int) printerType));
    Debug::trace("RealTimeController.PrinterManager", HobString("NewUSBPrinter() - prKind: ") + Integer::toString((int) prKind));

    // remove the printer comm from the list of unknown devices because it will either
    // be deleted or added to the list of known devices
    std::map< USBD_NODE_ID, Hobart::CEvolMsgReceiver *>::iterator pos( unknownDevices.find(nodeId) );

    if ( unknownDevices.end() != pos )
        unknownDevices.erase(pos);

    if (printerType == FirstPrinter)
    {
        Debug::trace("RealTimeController.PrinterManager", "NewUSBPrinter() - is first printer");
        if (pFirstPrinter == NULL)
        {
            Debug::trace("RealTimeController.PrinterManager", "NewUSBPrinter() - is first printer, and first is currently null");
            peripheralList.setFirstPrinter(prKind);
            dispatchEvent(&peripheralList);

			pFirstPrinterComm = pNewPComm;
			pFirstPrinter = pHT = new PrinterManager(
				pCreationDevice,
				pPrinterTeachTable,
				printerType,
				labelWidth,
				bufferSize,
				printheadSize,
				physicalAddress,
				nodeId,
				prKind);

            // Give the new PrinterManager some time to execute, at least so it can register for its messages,
            // since the call to firstPrinterAttached() will dispatch one the new PrinterManager is interested in.
            PAL_absclass::PAL_sleep( 1 );

            addDeviceToKnownList(nodeId, Printer, pCreationDevice, pFirstPrinter);

            currentModeCS.Enter(); // FT-1115
            if ( pCurrentMode )
            	pCurrentMode->firstPrinterAttached(pFirstPrinter);
            currentModeCS.Leave(); // FT-1115

            Debug::trace("RealTimeController.PrinterCommManager", HobString("pFirstPrinterComm: 0x") + Hex::toString((long long) pFirstPrinterComm));
            Debug::trace("RealTimeController.PrinterManager", HobString("pFirstPrinter: 0x") + Hex::toString((long long) pFirstPrinter));
        }
        else
        {
			// attaching EPP printer as secondary to APC
			if((pNewPComm->isUSBCommEnabled() == true) && ((!pFirstPrinterComm) || (pFirstPrinterComm->isUSBCommEnabled() == true)))
			{
				// Negotiation Strategy
				printerType = SecondPrinter;
			}
			else
			{
				if (pNewPComm->isUSBCommEnabled() == true)
				{
					removeDeviceFromKnownList(nodeId);
					addDeviceToKnownList(nodeId, Printer, pCreationDevice, pFirstPrinter);
				}

				delete pNewPComm;
			}
		}
	}

    if (printerType == SecondPrinter)
    {
    	PrinterManager *mgr( dynamic_cast<PrinterManager*>( pSecondPrinter ) );

		if ( mgr )
			if ( mgr->isFakePrinterManager() )
				detachFakePrinter(mgr->getUsbNodeId());

        if (pSecondPrinter == NULL)
        {
            peripheralList.setSecondPrinter(prKind);
            dispatchEvent(&peripheralList);

			pSecondPrinterComm = pNewPComm;
            pSecondPrinter = pHT = new PrinterManager(
				pCreationDevice,
				pPrinterTeachTable,
				printerType,
				labelWidth,
				bufferSize,
				printheadSize,
				physicalAddress,
				nodeId,
				prKind);

            // Give the new PrinterManager some time to execute, at least so it can register for its messages,
            // since the call to firstPrinterAttached() will dispatch one the new PrinterManager is interested in.
            PAL_absclass::PAL_sleep( 1 );

            addDeviceToKnownList(nodeId, Printer, pCreationDevice, pSecondPrinter);

            currentModeCS.Enter(); // FT-1115
            if ( pCurrentMode )
            	pCurrentMode->secondPrinterAttached(pSecondPrinter);
            currentModeCS.Leave(); // FT-1115

            Debug::trace("RealTimeController.PrinterCommManager", HobString("pSecondPrinterComm: 0x") + Hex::toString((long long) pSecondPrinterComm));
            Debug::trace("RealTimeController.PrinterManager", HobString("pSecondPrinter: 0x") + Hex::toString((long long) pSecondPrinter));
        }
        else
        {
			// attaching EPP printer as secondary to APC
			if((pNewPComm->isUSBCommEnabled() == true) && ((!pSecondPrinterComm) || (pSecondPrinterComm->isUSBCommEnabled() == true)))
			{
				// Negotiation Strategy
				printerType = ThirdPrinter;
			}
			else
			{
				if (pNewPComm->isUSBCommEnabled() == true)
				{
					removeDeviceFromKnownList(nodeId);
					addDeviceToKnownList(nodeId, Printer, pCreationDevice, pSecondPrinter);
				}
				delete pNewPComm;
			}
		}
    }

    if (printerType == ThirdPrinter)
    {
    	PrinterManager *mgr( dynamic_cast<PrinterManager*>( pThirdPrinter ) );

		if ( mgr )
			if ( mgr->isFakePrinterManager() )
				detachFakePrinter(mgr->getUsbNodeId());

        if (pThirdPrinter == NULL)
        {
            peripheralList.setThirdPrinter(prKind);
            dispatchEvent(&peripheralList);

			pThirdPrinterComm = pNewPComm;
			pThirdPrinter = pHT = new PrinterManager(
				pCreationDevice,
				pPrinterTeachTable,
				printerType,
				labelWidth,
				bufferSize,
				printheadSize,
				physicalAddress,
				nodeId,
				prKind);

            // Give the new PrinterManager some time to execute, at least so it can register for its messages,
            // since the call to firstPrinterAttached() will dispatch one the new PrinterManager is interested in.
            PAL_absclass::PAL_sleep( 1 );

            addDeviceToKnownList(nodeId, Printer, pCreationDevice, pThirdPrinter);

            currentModeCS.Enter(); // FT-1115
            if ( pCurrentMode )
            	pCurrentMode->thirdPrinterAttached(pThirdPrinter);
            currentModeCS.Leave(); // FT-1115

            Debug::trace("RealTimeController.PrinterCommManager", HobString("pThirdPrinterComm: 0x") + Hex::toString((long long) pThirdPrinterComm));
            Debug::trace("RealTimeController.PrinterManager", HobString("pThirdPrinter: 0x") + Hex::toString((long long) pThirdPrinter));
        }
        else
        {
			// attaching EPP printer as secondary to APC
			if((pNewPComm->isUSBCommEnabled() == true) && ((!pThirdPrinterComm) || (pThirdPrinterComm->isUSBCommEnabled() == true)))
			{
				// Negotiation Strategy
			}
			else
			{
				if (pNewPComm->isUSBCommEnabled() == true)
				{
					removeDeviceFromKnownList(nodeId);
					addDeviceToKnownList(nodeId, Printer, pCreationDevice, pThirdPrinter);
				}
				delete pNewPComm;
			}
        }
    }

    if (pHT != NULL)
    {
        DeviceType *pDT( new DeviceType );
        pDT->pHobThread = pHT;
        pDT->evolDevType = Printer;

        list<DeviceType *> *pList = usbDevices[nodeId];

        // Add it to the list of Peripherals attached to this usb node.
		if (pList)
			pList->push_back(pDT);
    }

    checkForVirtualPrinting();

	//SOF-3259 no 2nd or 3rd labels - Debug::trace("PrinterManager.checkForVirtualPrinting", "RTC.NewUSBPrinter() END");

    return pHT;
}

