void RealTimeController::checkForVirtualPrinting()
{
	PrinterManager *firstPrinter( dynamic_cast<PrinterManager*>( pFirstPrinter ) );
	PrinterManager *secondPrinter( dynamic_cast<PrinterManager*>( pSecondPrinter ) );
	PrinterManager *thirdPrinter( dynamic_cast<PrinterManager*>( pThirdPrinter ) );

	Debug::trace("PrinterManager", "checkForVirtualPrinting ..." );

	//SOF-3259 no 2nd or 3rd labels - Debug::trace("PrinterManager.checkForVirtualPrinting", "RTC.checkForVirtualPrinting firstPrinter: " + ptrtostring(firstPrinter));
	//SOF-3259 no 2nd or 3rd labels - Debug::trace("PrinterManager.checkForVirtualPrinting", "RTC.checkForVirtualPrinting secondPrinter: " + ptrtostring(secondPrinter));
	//SOF-3259 no 2nd or 3rd labels - Debug::trace("PrinterManager.checkForVirtualPrinting", "RTC.checkForVirtualPrinting thirdPrinter: "  + ptrtostring(thirdPrinter));

    // Virtual printing only exists if there is a primary printer, and no secondary or tertiary printer.
	// The above was the old rule, but needs to change now that we can hook up an EPP to an HTi, for printing product support texts.
	// So now, I'm removing the checks that the second and third printer managers are not there (NULL).
	// Any non-prepack scale will be set for virtual printing.

	if (firstPrinter)
	{
		//SOF-3259 no 2nd or 3rd labels - Debug::trace("PrinterManager.checkForVirtualPrinting", "RTC.checkForVirtualPrinting isPrepackScale(): " + util_string::booltostring(Configuration::getInstance()->isPrepackScale()) );
		//SOF-3259 no 2nd or 3rd labels - Debug::trace("PrinterManager.checkForVirtualPrinting", "RTC.checkForVirtualPrinting !isPrepackScale(): " + util_string::booltostring(!Configuration::getInstance()->isPrepackScale()));

		firstPrinter->setVirtualPrintingEnabled(!Configuration::getInstance()->isPrepackScale());
	}

	if ( secondPrinter )
		secondPrinter->setVirtualPrintingEnabled( false );

	if ( thirdPrinter )
		thirdPrinter->setVirtualPrintingEnabled( false );
}

bool RealTimeController::isVirtualPrintingEnabled()
{
	PrinterManager *firstPrinter( dynamic_cast<PrinterManager*>( pFirstPrinter ) );

    // Since the first printer can be the only one that handles virtual printer printing, that's the only one we have to check.
    return (( firstPrinter ) && ( firstPrinter->isVirtualPrintingEnabled() ));
}



void RealTimeController::addDeviceToKnownList(USBD_NODE_ID nodeId,
        EvolDeviceType evolDevType,
        Hobart::CEvolMsgReceiver *pComm,
        Hobart::CEvolMsgReceiver *pManager)
{
    Util::CLockCriticalSection lock( usbNodesCS );

    list<DeviceType *> *pList = NULL;
    map< USBD_NODE_ID, list<DeviceType *> *>::iterator pos;
    DeviceType *pDT = NULL;

    if ((pos = usbDevices.find(nodeId)) == usbDevices.end())
    {
        pList = new list<DeviceType *>;

        usbDevices.insert(make_pair(nodeId, pList));
    }
    else
    {
        pList = pos->second;
    }

    if (pComm != NULL)
    {
        pDT = new DeviceType;
        pDT->pHobThread = pComm;
        pDT->evolDevType = evolDevType;

        pList->push_front(pDT);
    }

    if (pManager != NULL)
    {
        pDT = new DeviceType;
        pDT->pHobThread = pManager;
        pDT->evolDevType = evolDevType;

        pList->push_back(pDT);
    }
}

void RealTimeController::removeDeviceFromKnownList(USBD_NODE_ID nodeId)
{
    Util::CLockCriticalSection lock( usbNodesCS );

    list<DeviceType *> *pList = NULL;
    map< USBD_NODE_ID, list<DeviceType *> *>::iterator pos;
    string strMsg;

    if ((pos = usbDevices.find(nodeId)) != usbDevices.end())
    {
        pList = pos->second;

        while (pList->size() > 0)
        {
            delete pList->front();
            pList->pop_front();
        }

        delete pList;

        usbDevices.erase(pos);
    }
}

