void RealTimeController::handleWeigherEvent(WgEvent wgEvent, const char *recvBuffer)
{
    switch (wgEvent)
    {
        case WgStatus: {
			WeigherStatus wgStatus(recvBuffer);

			if (((wgStatus.isManagerDeleted() == true) || (wgStatus.isPeripheralComm() == false)) &&
					(peripheralList.getFirstWeigher() != WgNoWeigher))
			{
				currentModeCS.Enter(); // FT-1115
				if(pCurrentMode)
					pCurrentMode->weigherDetached();
				currentModeCS.Leave(); // FT-1115

				pWeigherManager = NULL;
				Debug::trace("RealTimeController.WeigherManager", HobString("pWeigherManager: 0x") + Hex::toString((long long) pWeigherManager));


				peripheralList.setFirstWeigher(WgNoWeigher);
				dispatchEvent(&peripheralList);
			}
		}
		break;
        case WgKind: {
			WeigherWeigherKind wgKind(recvBuffer);

			if (wgKind.getWeigherKind() != peripheralList.getFirstWeigher())
			{
				peripheralList.setFirstWeigher(wgKind.getWeigherKind());
				dispatchEvent(&peripheralList);
			}
		}
		break;
        case WgKPCDetached: {
        	if( pWeigherManager != NULL ) {

        		Debug::trace("RealTimeController.WeigherManager", "WgKPCDetached!" );
        		delete pWeigherManager;
        		pWeigherManager = NULL;

				currentModeCS.Enter();
				if(pCurrentMode)
					pCurrentMode->weigherDetached();
				currentModeCS.Leave();
				Debug::trace("RealTimeController.WeigherManager", "WgKPCDetached dispatchEvent: peripheralList " );

				peripheralList.setFirstWeigher(WgNoWeigher);
				peripheralList.show();
				dispatchEvent(&peripheralList);
        	}
        }
    	break;
        default:
            break;
    }
}

