    Debug::trace("RealTimeController.WrapperManager", debugHeader+HobString("pWrapperManager: 0x") + Hex::toString((long long) pWrapperManager));
    Debug::trace("RealTimeController.OperatingMode", debugHeader+"######## Creating a new AutoWeighWrapperMode");
