void RealTimeController::handleWrapperAttached()
{
    static const HobString debugHeader("handleWrapperAttached(): ");
	
	Debug::trace("RealTimeController.WrapperManager", debugHeader+HobString("handleWrapperAttached():  Does this occur with the AWS/EWS???"));
	Debug::trace("RealTimeController.WrapperManager", debugHeader+HobString("pWrapperManager: 0x") + HobString(Hex::toString((long long) pWrapperManager)));

    WrapperSetWrapMode::WrapMode wrapMode = WrapperSetWrapMode::UnknownMode;

    switch (currentOpMode)
    {
        case OpModeManualWeigh:
        case OpModeProductionEntry:
        case OpModeAccumulateItems:
        case OpModeBuildAMeal:
            wrapMode = WrapperSetWrapMode::ManualWeigh;
            break;
        case OpModeSemiWeigh:
            wrapMode = WrapperSetWrapMode::WrapOff;
            break;
        case OpModeAutoWeigh:
            wrapMode = WrapperSetWrapMode::WrapOn;
            break;
        case OpModeWrapOnly:
            wrapMode = WrapperSetWrapMode::WrapOnly;
            break;
        case OpModeAutoManualApply:
            wrapMode = WrapperSetWrapMode::AutoManualApply;
            break;
        case OpModeSupervisor:
        case OpModeService:
            currentModeCS.Enter(); // FT-1115
            if ( pCurrentMode )
            	pCurrentMode->wrapperAttached(pWrapperManager, wrapMode);
            currentModeCS.Leave(); // FT-1115
            break;
        default:
            break;
    }

    Debug::trace("RealTimeController.WrapperManager", debugHeader+HobString("xxxpCurrentMode: 0x") + HobString(Hex::toString((long long) pCurrentMode)));
    Debug::trace("RealTimeController.WrapperManager", debugHeader+HobString("xxxwrapMode: 0x") + HobString(Integer::toString(wrapMode)));

    if (wrapMode != WrapperSetWrapMode::UnknownMode)
    {
        currentModeCS.Enter(); // FT-1115

		deleteCurrentMode(pCurrentMode);
		pCurrentMode = NULL;

		Debug::trace("RealTimeController.Error", debugHeader+HobString("Unknown Wrap Mode, deleting current mode!"));

        currentModeCS.Leave(); // FT-1115
    }

	ilaAttached = false;
	Debug::trace("RealTimeController.WrapperManager", debugHeader+HobString("Done"));
}

