WrapperSetWrapMode::WrapMode RealTimeController::getCurrentWrapMode()
{
    WrapperSetWrapMode::WrapMode wrapMode = WrapperSetWrapMode::UnknownMode;
    switch (currentOpMode)
    {
        case OpModeManualWeigh:
            wrapMode = WrapperSetWrapMode::ManualWeigh;
            break;
        case OpModeSemiWeigh:
            wrapMode = WrapperSetWrapMode::WrapOff;
            break;
        case OpModeAutoWeigh:
            wrapMode = WrapperSetWrapMode::WrapOn;
            break;
        case OpModeWrapOnly:
            wrapMode = WrapperSetWrapMode::WrapOnly;
            break;
        case OpModeAutoManualApply:
            wrapMode = WrapperSetWrapMode::AutoManualApply;
            break;
        case OpModeSupervisor:
        case OpModeService:
        default:
            break;
    }
    return wrapMode;
}

