bool RealTimeController::isNextGenWrapperEnabled()
{
	bool result ( false );

#if defined ( __linux__ )
	FpmManager *pSerialFlash( FpmManager::getInstance() );

	std::string systemStyle;

	/* =========== This is the PrePack configuration matrix ===========
	 * Scale style determines which components the scale is attached.
	 * 		EPCP-X X X X
	 * 			 ^ ^ ^ ^
	 * 			 | | | |__ Power: U = 198v - 242v, T = 187v - 197v or 243v - 254v, I = International (Chile)
	 * 			 | | |__ Generation: 1 = BCM CAN1 USB SAM7, 2 = ACR CAN1 USB SAM7
	 * 			 | |__ Processor: S = Solo ARM, I = Dual ARM, Q = Quad ARM, X = x86
	 * 			 |__ OS: 5 = Linux, 6 = Windows
	 *
	 * 		NGWX-X X X X XX XX
	 * 		   ^ ^ ^ ^ ^ ^  ^
	 * 		   | | | | | |  |__ Customer variants
	 * 		   | | | | | |__ Discharge
	 * 		   | | | | |__ Power
	 * 		   | | | |__ Generation
	 * 		   | | |__ Processor
	 * 		   | |__ OS
	 * 		   |__ #Rolls
	 *
	 *	Rolls: 1,2
	 *	OS: L,W
	 *	Processor: S,I,Q,X	S = Solo ARM, I = Dual ARM, Q = Quad ARM, X = x86
	 *	Generation: 1,2,3	1 = BCM CAN1 USB SAM7, 2 = ACR CAN1 USB SAM7, 3 = ACR CAN2 RS485 K64
	 *	Power: U,T,I		U = 198v - 242v, T = 187v - 197v or 243v - 254v, I = international (Chile)
	 *	Discharge: LR,RL 	LR = Left to Right, RL = Right to Left
	 *
	 *	EPCP-5I1 or EPCP-5I2: support AWS3 Enhanced
	 *	NGWX-XX1 or NGWX-XX2: support NGW1 or NGW2
	 *	NGWX-XX3:			  support NGW3
	 */



	Debug::trace("RealTimeController", "Reading system style. ");
	if ( pSerialFlash )
	{
		systemStyle = pSerialFlash->getMFGSystemStyle();

		if ( !systemStyle.empty() )
			Debug::trace("RealTimeController", "System type: " + systemStyle );
	}

	if (( systemStyle == "AWS3" ) || (systemStyle == "NGW1" ) || (systemStyle == "NGW2") || (systemStyle == "NGW3" ) )
	{
		Debug::trace("RealTimeController", "NGW Enabled!");
		result = true;
	}
#endif

	return result;
}

bool RealTimeController::startupNextGenWrapper()
{
	Debug::trace("RealTimeController", "Enable USB Peripherals.");
	string reset = "/bin/echo 1 >> /usr/local/gpio/hub1_enable/value";
	string result;
	PAL_absclass::PAL_executeWithResults(reset.c_str(), result);

	SystemStartManager *pSystemManager( SystemStartManager::getInstance() );

	Debug::trace("RTC.Test", "Coldstart");

	return pSystemManager->setModeToScan( true );
}

bool RealTimeController::isNextGenServiceScale()
{
	bool result ( false );
	FpmManager *pSerialFlash( FpmManager::getInstance() );

	std::string systemStyle;
	if ( pSerialFlash ) {
		systemStyle = pSerialFlash->getMFGSystemStyle();

		if ( !systemStyle.empty() )
			Debug::trace("RealTimeController", "System type: " + systemStyle );
	}

	if( ( systemStyle == "HTK")  || ( systemStyle == "FSS" ) ) {
		Debug::trace("RealTimeController", "HTK Enabled!");
		result = true;
	}

	return result;
}

void RealTimeController::startupNextGenServiceScale()
{
	//hub1 must be enabled to release KPC from reset
	Debug::trace("RealTimeController", "Enable KPC Peripheral.");

	string reset = "/bin/echo 1 >> /usr/local/gpio/hub1_enable/value";
	string result;
	PAL_absclass::PAL_executeWithResults(reset.c_str(), result);

	SystemStartManager *pSystemManager( SystemStartManager::getInstance() );


}


RealTimeController *RealTimeController::getInstance()
{
    if ( instance == 0 ) {
		//SOF-3748
		instanceMutex_.acquire();
		if( instance == 0 ) {
			Debug::trace("RealTimeController", "instance: " + Hex::toString((void*)instance) );
			instance = new RealTimeController();
			Debug::trace("RealTimeController", "instance: " + Hex::toString((void*)instance) );
		}
		//SOF-3748
		instanceMutex_.release();
    }
    return instance;
}

RealTimeController *RealTimeController::instance = (RealTimeController *) NULL;
